import products from './products.json' with { type: 'json' };

export async function listTools() {
  return [
    {
      name: 'inventory_search',
      description: 'Search product names case-insensitively',
      inputSchema: {
        type: 'object',
        properties: {
          query: { type: 'string', description: 'Search query' },
          limit: { type: 'integer', description: 'Max results (1-10)', minimum: 1, maximum: 10 }
        },
        required: ['query']
      }
    }
  ];
}

export async function callTool(name, args) {
  if (name !== 'inventory_search') {
    throw new Error(`Unknown tool: ${name}`);
  }

  // Validate query is required and is a string
  if (args === undefined || args === null || typeof args !== 'object') {
    throw new Error('Arguments are required');
  }
  if (typeof args.query !== 'string') {
    throw new Error('query is required and must be a string');
  }

  // Validate limit if provided
  let limit;
  if (args.limit !== undefined) {
    if (typeof args.limit !== 'number' || !Number.isInteger(args.limit)) {
      throw new Error('limit must be an integer');
    }
    if (args.limit < 1 || args.limit > 10) {
      throw new Error('limit must be between 1 and 10');
    }
    limit = args.limit;
  }

  // Case-insensitive search
  const query = args.query.toLowerCase();
  let results = products.filter(p => p.name.toLowerCase().includes(query));

  // Apply limit if specified
  if (limit !== undefined) {
    results = results.slice(0, limit);
  }

  return {
    content: [
      { type: 'text', text: JSON.stringify(results) }
    ]
  };
}

